import re

UNIT_ALIASES = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'week': 604800, 'weeks': 604800,
}

_COMPONENT_RE = re.compile(r'(\d+(?:\.\d+)?)\s*([A-Za-z]+)')

_ISO_RE = re.compile(
    r'^[Pp]'
    r'(?:(\d+(?:\.\d+)?)[Ww])?'
    r'(?:(\d+(?:\.\d+)?)[Dd])?'
    r'(?:[Tt]'
    r'(?:(\d+(?:\.\d+)?)[Hh])?'
    r'(?:(\d+(?:\.\d+)?)[Mm])?'
    r'(?:(\d+(?:\.\d+)?)[Ss])?'
    r')?$'
)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("duration must be a string")

    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if re.fullmatch(r'\d+', s):
        return int(s)

    if s[0] in 'Pp':
        return _parse_iso8601(s)

    if re.fullmatch(r'\d+:\d+(:\d+)?', s):
        parts = [int(p) for p in s.split(':')]
        if len(parts) == 2:
            minutes, seconds = parts
            return minutes * 60 + seconds
        hours, minutes, seconds = parts
        return hours * 3600 + minutes * 60 + seconds

    return _parse_components(s)


def _parse_iso8601(s: str) -> int:
    m = _ISO_RE.fullmatch(s)
    if not m or all(g is None for g in m.groups()):
        raise ValueError(f"invalid ISO8601 duration: {s!r}")

    weeks, days, hours, minutes, seconds = (
        float(g) if g else 0.0 for g in m.groups()
    )
    total = (
        weeks * 604800
        + days * 86400
        + hours * 3600
        + minutes * 60
        + seconds
    )
    return round(total)


def _parse_components(s: str) -> int:
    pos = 0
    total = 0.0
    matched_any = False

    for match in _COMPONENT_RE.finditer(s):
        gap = s[pos:match.start()]
        if gap.strip() != '':
            raise ValueError(f"invalid duration: {s!r}")

        number = float(match.group(1))
        unit = match.group(2).lower()
        multiplier = UNIT_ALIASES.get(unit)
        if multiplier is None:
            raise ValueError(f"unknown unit: {unit!r}")

        total += number * multiplier
        pos = match.end()
        matched_any = True

    if not matched_any or s[pos:].strip() != '':
        raise ValueError(f"invalid duration: {s!r}")

    if total < 0:
        raise ValueError(f"negative duration: {s!r}")

    return round(total)

